const payload = $json.body ?? $json;

const feedbackId = parseInt(payload.feedback_id ?? 0, 10) || 0;
const rating = parseInt(payload.rating ?? 0, 10) || 0;
const content = String(payload.content || '').trim();
const callback = payload.callback || {};

const prompt = [
  'You are reviewing user feedback for SharedSpace.',
  'Your task is to classify the written sentiment and decide whether the text matches the star rating.',
  '',
  'Rules:',
  '- 4 or 5 stars usually align with positive feedback.',
  '- 3 stars usually align with mixed or neutral feedback.',
  '- 1 or 2 stars usually align with negative feedback.',
  '- If the comment tone clearly conflicts with the rating, mark sentiment_status as contradiction.',
  '- If the comment is unclear or too short, mark sentiment_status as unclear.',
  '- Only use these sentiment_label values: positive, neutral, negative, mixed, unclear.',
  '- Only use these sentiment_status values: aligned, mixed, contradiction, unclear.',
  '- sentiment_score must be a number from -1 to 1.',
  '',
  `Rating: ${rating}/5`,
  `Comment: ${content || '[empty]'}`
].join('\n');

return [{
  json: {
    feedback_id: feedbackId,
    rating,
    content,
    callback_url: String(callback.url || ''),
    callback_secret: String(callback.secret || ''),
    ai_request: {
      model: 'openai/gpt-oss-20b',
      messages: [
        {
          role: 'system',
          content: 'Return valid JSON only.'
        },
        {
          role: 'user',
          content: prompt
        }
      ],
      response_format: {
        type: 'json_object'
      },
      temperature: 0,
      max_completion_tokens: 300
    }
  }
}];

const upstream = $items('Build Sentiment Request', 0, 0)?.json || {};
const raw = $json.choices?.[0]?.message?.content || '{}';
const cleaned = String(raw).replace(/```json|```/gi, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = {
    sentiment_label: 'unclear',
    sentiment_score: 0,
    sentiment_status: 'unclear'
  };
}

const allowedLabels = new Set(['positive', 'neutral', 'negative', 'mixed', 'unclear']);
const allowedStatuses = new Set(['aligned', 'mixed', 'contradiction', 'unclear']);

const label = allowedLabels.has(parsed.sentiment_label) ? parsed.sentiment_label : 'unclear';
const status = allowedStatuses.has(parsed.sentiment_status) ? parsed.sentiment_status : 'unclear';
const score = Math.max(-1, Math.min(1, Number(parsed.sentiment_score ?? 0) || 0));
const approval = status === 'aligned' ? 1 : 0;

return [{
  json: {
    feedback_id: upstream.feedback_id,
    callback_url: upstream.callback_url,
    callback_secret: upstream.callback_secret,
    callback_payload: {
      feedback_id: upstream.feedback_id,
      sentiment_label: label,
      sentiment_score: score,
      sentiment_status: status,
      is_approved: approval
    }
  }
}];
